#include "zlang/Parser.h"
#include <cstdlib>
namespace zlang {const Token&Parser::p(std::size_t n)const{return t_[std::min(i_+n,t_.size()-1)];}bool Parser::at(TokenKind k)const{return p().kind==k;}bool Parser::take(TokenKind k){if(at(k)){++i_;return true;}return false;}const Token&Parser::need(TokenKind k,const char*m){if(!at(k)){d_.error(p().span,m);return p();}return t_[i_++];}void Parser::terms(){while(take(TokenKind::NewLine)||take(TokenKind::Semicolon)){} }
Program Parser::parse(){Program z;terms();while(!at(TokenKind::Eof)){z.functions.push_back(function());terms();if(d_.hasErrors()&&at(TokenKind::Eof))break;}return z;}std::unique_ptr<Function>Parser::function(){auto f=std::make_unique<Function>();auto&n=(at(TokenKind::Main)?need(TokenKind::Main,"function name expected"):need(TokenKind::Identifier,"function name expected"));f->name=n.lexeme;f->span.begin=n.span.begin;need(TokenKind::LParen,"expected '('");if(!at(TokenKind::RParen)){do{f->params.push_back(need(TokenKind::Identifier,"parameter expected").lexeme);}while(take(TokenKind::Comma));}need(TokenKind::RParen,"expected ')'");terms();f->body=block();f->span.end=f->body->span.end;return f;}std::unique_ptr<Block>Parser::block(){auto b=std::make_unique<Block>();auto&o=need(TokenKind::LBrace,"expected '{'");b->span.begin=o.span.begin;terms();while(!at(TokenKind::RBrace)&&!at(TokenKind::Eof)){b->statements.push_back(statement());terms();}auto&c=need(TokenKind::RBrace,"expected '}'");b->span.end=c.span.end;return b;}
StmtPtr Parser::statement(){if(at(TokenKind::Box)||at(TokenKind::Line)||at(TokenKind::Bool)||at(TokenKind::Cpx)){auto s=std::make_unique<VarDecl>();auto k=p().kind;s->span.begin=p().span.begin;++i_;s->type=k==TokenKind::Box?Type::Box:k==TokenKind::Line?Type::Line:k==TokenKind::Bool?Type::Bool:Type::Cpx;s->name=need(TokenKind::Identifier,"variable name expected").lexeme;need(TokenKind::Assign,"expected '='");s->init=expression();s->span.end=s->init->span.end;return s;}if(take(TokenKind::Print)){auto s=std::make_unique<Print>();s->span.begin=t_[i_-1].span.begin;bool par=take(TokenKind::LParen);if(!(par&&at(TokenKind::RParen))&&!at(TokenKind::NewLine)&&!at(TokenKind::Semicolon)){do{s->args.push_back(expression());}while(take(TokenKind::Comma));}if(par)need(TokenKind::RParen,"expected ')'");s->span.end=p().span.begin;return s;}if(take(TokenKind::If)){auto s=std::make_unique<If>();s->span.begin=t_[i_-1].span.begin;need(TokenKind::LParen,"expected '('");s->cond=expression();need(TokenKind::RParen,"expected ')'");terms();s->thenBlock=block();terms();while(take(TokenKind::Else)){if(take(TokenKind::If)){need(TokenKind::LParen,"expected '('");auto c=expression();need(TokenKind::RParen,"expected ')'");terms();s->elseIfs.push_back({std::move(c),block()});terms();}else{s->elseBlock=block();break;}}s->span.end=(s->elseBlock?s->elseBlock->span.end:s->thenBlock->span.end);return s;}if(take(TokenKind::While)){auto s=std::make_unique<While>();s->span.begin=t_[i_-1].span.begin;need(TokenKind::LParen,"expected '('");s->cond=expression();need(TokenKind::RParen,"expected ')'");terms();s->body=block();s->span.end=s->body->span.end;return s;}if(take(TokenKind::For)){auto s=std::make_unique<For>();s->span.begin=t_[i_-1].span.begin;s->name=need(TokenKind::Identifier,"loop variable expected").lexeme;need(TokenKind::In,"expected 'in'");need(TokenKind::Plus,"expected '+('");need(TokenKind::LParen,"expected '('");s->end=expression();need(TokenKind::RParen,"expected ')'");terms();s->body=block();s->span.end=s->body->span.end;return s;}if(take(TokenKind::Return)){auto s=std::make_unique<Return>();s->span.begin=t_[i_-1].span.begin;if(!at(TokenKind::NewLine)&&!at(TokenKind::Semicolon)&&!at(TokenKind::RBrace))s->value=expression();s->span.end=p().span.begin;return s;}if(at(TokenKind::Identifier)&&p(1).kind==TokenKind::Assign){auto s=std::make_unique<Assign>();s->span.begin=p().span.begin;s->name=p().lexeme;i_+=2;s->value=expression();s->span.end=s->value->span.end;return s;}auto s=std::make_unique<ExprStmt>();s->expr=expression();s->span=s->expr->span;return s;}
ExprPtr Parser::expression(){return equality();}ExprPtr Parser::equality(){auto x=comparison();while(at(TokenKind::EqEq)||at(TokenKind::NotEq)){auto op=p().lexeme;++i_;auto y=comparison();auto n=std::make_unique<BinaryExpr>();n->span={x->span.begin,y->span.end};n->lhs=std::move(x);n->op=op;n->rhs=std::move(y);x=std::move(n);}return x;}ExprPtr Parser::comparison(){auto x=additive();while(at(TokenKind::Less)||at(TokenKind::LessEq)||at(TokenKind::Greater)||at(TokenKind::GreaterEq)){auto op=p().lexeme;++i_;auto y=additive();auto n=std::make_unique<BinaryExpr>();n->span={x->span.begin,y->span.end};n->lhs=std::move(x);n->op=op;n->rhs=std::move(y);x=std::move(n);}return x;}ExprPtr Parser::additive(){auto x=multiply();while(at(TokenKind::Plus)||at(TokenKind::Minus)){auto op=p().lexeme;++i_;auto y=multiply();auto n=std::make_unique<BinaryExpr>();n->span={x->span.begin,y->span.end};n->lhs=std::move(x);n->op=op;n->rhs=std::move(y);x=std::move(n);}return x;}ExprPtr Parser::multiply(){auto x=unary();while(at(TokenKind::Star)||at(TokenKind::Slash)){auto op=p().lexeme;++i_;auto y=unary();auto n=std::make_unique<BinaryExpr>();n->span={x->span.begin,y->span.end};n->lhs=std::move(x);n->op=op;n->rhs=std::move(y);x=std::move(n);}return x;}ExprPtr Parser::unary(){if(at(TokenKind::Plus)||at(TokenKind::Minus)){auto o=p();++i_;auto n=std::make_unique<UnaryExpr>();n->span.begin=o.span.begin;n->op=o.lexeme;n->rhs=unary();n->span.end=n->rhs->span.end;return n;}return call();}ExprPtr Parser::call(){auto x=primary();while(take(TokenKind::LParen)){auto n=std::make_unique<CallExpr>();n->span.begin=x->span.begin;if(auto*q=dynamic_cast<NameExpr*>(x.get()))n->callee=q->name;else d_.error(x->span,"only a function name can be called");if(!at(TokenKind::RParen)){do{n->args.push_back(expression());}while(take(TokenKind::Comma));}n->span.end=need(TokenKind::RParen,"expected ')'").span.end;x=std::move(n);}return x;}ExprPtr Parser::primary(){auto t=p();if(take(TokenKind::Integer)){auto n=std::make_unique<LiteralExpr>();try{n->value=(std::int64_t)std::stoll(t.lexeme);}catch(...){d_.error(t.span,"integer literal is outside int64 range");n->value=(std::int64_t)0;}n->span=t.span;return n;}if(take(TokenKind::Floating)){auto n=std::make_unique<LiteralExpr>();n->value=std::stod(t.lexeme);n->span=t.span;return n;}if(take(TokenKind::String)){auto n=std::make_unique<LiteralExpr>();n->value=t.lexeme;n->span=t.span;return n;}if(take(TokenKind::True)||take(TokenKind::False)){auto n=std::make_unique<LiteralExpr>();n->value=t.kind==TokenKind::True;n->span=t.span;return n;}if(take(TokenKind::Identifier)||take(TokenKind::Cpx)){auto n=std::make_unique<NameExpr>();n->name=t.lexeme;n->span=t.span;return n;}if(take(TokenKind::LParen)){auto n=expression();need(TokenKind::RParen,"expected ')'");return n;}d_.error(t.span,"expected expression");++i_;auto n=std::make_unique<LiteralExpr>();n->value=(std::int64_t)0;n->span=t.span;return n;}}
